module tb_TopModule();

    reg clk;
    reg load;
    reg [9:0] data;
    wire tc;

    TopModule dut (
        .clk(clk),
        .load(load),
        .data(data),
        .tc(tc)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        load = 0;
        data = 0;

        // Load 3 cycles
        @(posedge clk);
        load = 1;
        data = 3;
        @(posedge clk);
        load = 0;

        // Count should be 3 -> 2 -> 1 -> 0
        // At load cycle (t=0): count loaded with 3. tc = 0.
        // Cycle 1 (load=0): count becomes 2. tc = 0.
        // Cycle 2 (load=0): count becomes 1. tc = 0.
        // Cycle 3 (load=0): count becomes 0. tc = 1.

        // Wait 3 cycles
        @(posedge clk); // count=2
        #1; if (tc !== 0) $display("Error at cycle 1: tc=%b", tc);

        @(posedge clk); // count=1
        #1; if (tc !== 0) $display("Error at cycle 2: tc=%b", tc);

        @(posedge clk); // count=0
        #1; if (tc !== 1) $display("Error at cycle 3: tc=%b", tc);

        // Test loading while counting
        @(posedge clk);
        load = 1;
        data = 2;
        @(posedge clk);
        load = 0;
        // count loaded with 2, then decrements:
        // Cycle 1: count=1, tc=0
        // Cycle 2: count=0, tc=1

        @(posedge clk); // count=1
        #1; if (tc !== 0) $display("Error reload cycle 1: tc=%b", tc);

        @(posedge clk); // count=0
        #1; if (tc !== 1) $display("Error reload cycle 2: tc=%b", tc);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
